import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 13 — Parallel and Background Agents","description":"","frontmatter":{"source":"weeks/13-parallel-agents/README.md"},"headers":[],"relativePath":"weeks/13-parallel-agents/index.md","filePath":"weeks/13-parallel-agents/index.md"}'),n={name:"weeks/13-parallel-agents/index.md"};function s(i,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="week-13--parallel-and-background-agents" tabindex="-1">Week 13 — Parallel and Background Agents <a class="header-anchor" href="#week-13--parallel-and-background-agents" aria-label="Permalink to &quot;Week 13 — Parallel and Background Agents&quot;">​</a></h1><blockquote><p>Agents parallelize writing code, not reviewing it: run three at once and you become the integrator, and your own review time becomes the bottleneck worth measuring.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>The reading and your reading response · submit the week 12 eval report (the Seminar opens with its quiz) · M2 and peer evaluation 2 are due before this Seminar · CS [5xxx]: the critique is due before this Seminar</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz · talk: worktrees, cloud agents, orchestration, merge conflicts, governance, cost, and the evidence on agent-authored PRs (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-13.html" target="_blank" rel="noreferrer">slides</a>) · reading discussion · demo: two agents, two worktrees, one conflict · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--three-agents-one-integrator-75-min">Three agents, one integrator</a>: three <code>roomly</code> issues, three agents in parallel (one may be a background agent), then review and integrate all three, timing your own review. <strong>Checkoff:</strong> three branches integrated, CI green</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--a-process-retrospective-with-data">assignment</a>, your team&#39;s process retrospective with data, team-written, with an individual section per member</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: the three issues, and scripts that pull and compute your team&#39;s numbers · 🟡 AI limited: the retrospective (an AI may help with tables; the analysis and your individual section are yours) · 🔴 AI off: your reviews of the agents&#39; work, the quiz, the reading response</td></tr><tr><td><strong>Reading</strong></td><td>Peralta et al., &quot;Why Are Agentic Pull Requests Merged or Rejected?&quot; (<a href="#reading">below</a>)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words, 🔴 AI off, on Canvas, before the Seminar (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td>M2 was due before this Seminar. This week&#39;s assignment is your team&#39;s retrospective, which feeds the final report&#39;s process section (<a href="./../../project/milestones.html#the-full-timeline">milestones</a>). Background agents run only on your own fork or team fork (<a href="./../../project/#agents-in-the-team-fork">agents in the team fork</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td>No new deliverable. Keep the study moving toward the week 14 paper draft (<a href="./../../graduate/empirical-study.html#milestones">empirical study</a>)</td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h)</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Background agents act while you&#39;re not watching.</strong> Give them only a repository you own (your <code>roomly</code> copy or your own fork), never the course&#39;s template, another team&#39;s fork or an upstream project. Use the narrowest permissions the tool allows; never let an agent push to <code>main</code> or post where others will read it, and never start one on a metered allowance whose spending cap isn&#39;t at zero or its lowest value (<a href="./../../setup/safety-contract.html#6-spending-caps-at-zero">safety contract rules 5, 6 and 10</a>).</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Run several agents at once in <a href="./../../resources/glossary.html#worktree">git worktrees</a>, each on its own branch, and name each task&#39;s merge point before starting.</li><li>Delegate an issue to a <a href="./../../resources/glossary.html#background-agent">background agent</a> safely: your own repository, narrow permissions, a draft you review first.</li><li>Integrate parallel branches one at a time, resolve textual conflicts, and catch semantic ones with the full test suite and CI.</li><li>Measure your own review and integration time, and use it to decide how much to run in parallel.</li><li>Read the evidence on agent-authored PRs (merge rates, follow-up fixes, review burden), and analyze your team&#39;s own process with defined, reproducible metrics.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Minutes</th><th>What happens</th></tr></thead><tbody><tr><td>Due-date quiz</td><td>7</td><td>On your week 12 eval report, 🔴 AI off (<a href="./../../assessment/quizzes.html">quizzes</a>)</td></tr><tr><td>Concept talk</td><td>25</td><td>Worktrees and merge points; cloud agents; orchestration and <a href="./../../resources/glossary.html#subagent">subagents</a>; conflicts; <a href="./../../resources/glossary.html#human-in-the-loop">human-in-the-loop</a> governance; cost; the evidence (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-13.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>Reading discussion</td><td>20</td><td>What &quot;merged&quot; and &quot;rejected&quot; measure, then: which numbers will your team&#39;s retrospective report, and how will you define each?</td></tr><tr><td>Live demo</td><td>10</td><td>Two agents in two worktrees on two issues; one merge conflict resolved; the full suite after the merge</td></tr><tr><td>Lab preview</td><td>5</td><td>Prepare before the Lab: a fresh <code>roomly</code> copy with CI, agents that start, a background agent connected if you&#39;ll use one</td></tr></tbody></table><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The <a href="./lab.html">lab</a> uses the <a href="https://github.com/Boyu-Zhang-UOI/eswa-roomly" target="_blank" rel="noreferrer"><code>roomly</code> kit</a> again, in a fresh copy: its <code>ISSUES.md</code> holds eight small, independent issues with acceptance criteria. You read the code to predict which files each issue touches and where the branches will meet, choose three issues so that at least two collide, and start three agents at once: two CLI agents in worktrees and, if its allowance permits (<a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a>), a background agent working from an issue in your repository. Then you review each branch with a timer running, integrate them one at a time, and get CI green on the result.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Peralta et al., <a href="https://arxiv.org/abs/2605.22534" target="_blank" rel="noreferrer">&quot;Why Are Agentic Pull Requests Merged or Rejected? An Empirical Study&quot;</a></strong> (MSR 2026), the reading list&#39;s <a href="./../../resources/reading-list.html#week-13--parallel-and-background-agents">core pick</a>. In 717 cases inspected by hand (from 9,799 reviewed agent PRs), only 35.7% of rejections were clear agent failures; 31.2% came from workflow constraints, and 33.1% had no visible rationale. &quot;Rejected&quot; is a noisy label for &quot;bad&quot;, and &quot;merged&quot; may be a noisy label for &quot;good&quot;.</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off, on Canvas): Say what the merge rate of agent PRs does and doesn&#39;t measure, using one number from the paper. Then design one metric your team could compute from its own fork that is closer to &quot;the agent&#39;s work was good&quot;: define it precisely (what starts and stops the clock, or what counts), say where the data comes from, and name one way it could still mislead you. End with one question for the Seminar.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>Name the merge point first.</strong> &quot;Parallelize a task once you can name its merge point&quot; (UT Austin CS 378). Two tasks in one module are a conflict you scheduled (<a href="./../../resources/agent-patterns.html#worktrees">agent patterns</a>).</li><li><strong>Worktrees isolate files, not everything:</strong> each needs its own install, port and data folder.</li><li><strong>Background agents trade watching for reviewing.</strong> An issue goes in, a branch or draft PR comes out; you read it before anyone else does. Their limits and allowances are in <a href="./../../TOOLS.html#the-stack-at-a-glance">Tool Handout: The stack at a glance</a>.</li><li><strong>Orchestration multiplies cost and summaries.</strong> Each subagent spends from the same allowance, and its summary is inferred until you check it (<a href="./../../resources/agent-patterns.html#subagents">agent patterns</a>).</li><li><strong>Textual conflicts are the easy ones.</strong> Two branches can merge cleanly and still break together (two routes on one path, two edits to one API table). Run the full suite after each merge and let CI check the integrated commit.</li><li><strong>Merged is not the same as good.</strong> Of 567 PRs written with one CLI agent, 83.8% were merged, but 45.1% of those needed further changes (<a href="https://arxiv.org/abs/2509.14745" target="_blank" rel="noreferrer">Watanabe et al.</a>). In 2025, none of 15 reviewed agent PRs was mergeable as-is, and fixing each took 42 minutes on average (<a href="https://metr.org/blog/2025-08-12-research-update-towards-reconciling-slowdown-with-time-horizons" target="_blank" rel="noreferrer">METR</a>).</li><li><strong>Review is the bottleneck, and the evidence is thin.</strong> AI review raised average PR closure time from 5h52m to 8h20m at one company (<a href="https://arxiv.org/abs/2412.18531" target="_blank" rel="noreferrer">Cihan et al.</a>); no course has published outcome data on parallel agents. Your own numbers this week are worth collecting carefully.</li><li><strong>Governance is controls, not promises:</strong> agents never push to <code>main</code>, branch protection requires a human approval, people write PR descriptions, and <code>Assisted-by:</code> trailers disclose AI help.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>Two agents edit different functions in <code>server.js</code>. Will their branches conflict? How would you find out before merging?</li><li>Both branches pass their own tests, and the merge is clean, but <code>npm test</code> fails after it. Name two ways that happens.</li><li>Three agents finish in 6 minutes each; your review takes 12 minutes per branch. What did parallelism save, and what would you change?</li><li>Your team&#39;s agent PRs merged 90% of the time. What else do you need before calling them good?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>No background agent available:</strong> run a third CLI agent in a third worktree, and log the switch.</li><li><strong>Your free tier runs out mid-Lab:</strong> move one agent to the lab machine (<a href="./../../TOOLS.html#spreading-the-work-across-free-allowances">Tool Handout: Spreading the work across free allowances</a>); three agents on one free key share one rate limit.</li><li><strong>Actions is down:</strong> run <code>npm test</code> on the integrated commit, keep the output, and push when Actions is back. Worktree problems: <a href="./../../resources/troubleshooting.html#git-worktrees">troubleshooting</a>.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Murphy-Hill, Butler &amp; Savelieva, <a href="https://arxiv.org/abs/2607.01418" target="_blank" rel="noreferrer">&quot;Adoption and Impact of Command-Line AI Coding Agents&quot;</a>: at Microsoft, adopters merged about 24% more PRs than their counterfactual, for four months.</li><li>Robbes et al., <a href="https://arxiv.org/abs/2601.18341" target="_blank" rel="noreferrer">&quot;Agentic Much?&quot;</a>: 22.2–28.7% of 128,018 GitHub projects had adopted coding agents.</li><li>Previous week: <a href="./../12-evals/">Evals</a>. Next week: <a href="./../14-evidence-and-responsibility/">Evidence and Responsibility</a>, where your retrospective&#39;s numbers meet the published ones.</li></ul>',23)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
